Lemma joint_update_node_output_140 inputs path old current result :
 (exists ground bits, VM.find 123 old = Some (Gval ground bits)) ->
 formal_value_iter (formal_invalid_policy inputs path) flat_memories old false current flat_statements = Some result ->
 exists ground bits, VM.find 140 result = Some (Gval ground bits).
Proof.
 intros H123 Step.
 eapply (selected_node_concrete_ground_output joint_update_node_offsets flat_statements joint_update_expected_nodes 140 joint_update_expr_140 inputs path flat_memories old current result).
 - exact joint_update_node_positions.
 - exact joint_update_node_safety.
 - apply (@List.nth_error_In _ joint_update_expected_nodes 0 (140,joint_update_expr_140)). vm_compute. reflexivity.
 - apply joint_update_ready_140; assumption.
 - exact Step.
Qed.
